// ---------- audio (WebAudio, no assets) ----------
let AC = null;
function audio() { if (!AC) AC = new (window.AudioContext || window.webkitAudioContext)(); if (AC.state === "suspended") AC.resume(); return AC; }
function beep(freq, dur, type, vol, slideTo) {
  const ac = audio(); const t = ac.currentTime;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type || "square"; o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
  g.gain.setValueAtTime(vol || 0.15, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(g); g.connect(ac.destination);
  o.start(t); o.stop(t + dur + 0.02);
}
function noiseBurst(dur, vol, hp) {
  const ac = audio(); const t = ac.currentTime;
  const len = Math.max(1, (ac.sampleRate * dur) | 0);
  const buf = ac.createBuffer(1, len, ac.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = ac.createBufferSource(); src.buffer = buf;
  const f = ac.createBiquadFilter(); f.type = "highpass"; f.frequency.value = hp || 800;
  const g = ac.createGain(); g.gain.setValueAtTime(vol || 0.3, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  src.connect(f); f.connect(g); g.connect(ac.destination);
  src.start(t);
}
const sfx = {
  draw: p => beep(120 + p * 200, 0.05, "sawtooth", 0.05),
  shoot: () => { noiseBurst(0.12, 0.25, 1200); beep(300, 0.1, "square", 0.1, 80); },
  pop: () => { noiseBurst(0.15, 0.4, 500); beep(600, 0.08, "square", 0.2, 150); },
  miss: () => beep(150, 0.2, "triangle", 0.12, 60),
  win: () => { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => beep(f, 0.15, "square", 0.15), i * 110)); },
  lose: () => { [400, 300, 200, 120].forEach((f, i) => setTimeout(() => beep(f, 0.2, "sawtooth", 0.15), i * 150)); },
  click: () => beep(800, 0.05, "square", 0.1),
};

