  mode: "title", // title | play | over | win
  score: 0, arrows: 15, target: 10,
  balloons: [], arrowsF: [], parts: [], rings: [],
  aim: { x: W * 0.6, y: H * 0.4 },
  drawing: false, drawT: 0, lastDrawTick: 0,
  time: 0, shake: 0,
};

function rand(a, b) { return a + Math.random() * (b - a); }

function spawnBalloon() {
  const colors = ["#ff3355", "#ffcc00", "#33ccff", "#66ff66", "#ff66ff", "#ff8833"];
  state.balloons.push({
    x: rand(W * 0.35, W * 0.92), y: GROUND + 30,
    r: rand(22, 34), vy: -rand(40, 70), sway: rand(0, 6.28), swaySpd: rand(0.8, 1.6),
    color: colors[(Math.random() * colors.length) | 0],
    string: rand(28, 44),
  });
}

function reset() {
  state.score = 0; state.arrows = 15; state.balloons = [];
  state.arrowsF = []; state.parts = []; state.rings = [];
  state.mode = "play"; state.drawT = 0; state.drawing = false;
  for (let i = 0; i < 4; i++) spawnBalloon();
}

